<!-- Adapted from the Vue Bits GooeyNav source supplied by the site owner. Styles are namespaced to avoid affecting PillNav or the gallery. -->
<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,nextTick} from 'vue';
interface GooeyNavItem{label:string;href:string|null;}
interface GooeyNavProps{items:GooeyNavItem[];animationTime?:number;particleCount?:number;particleDistances?:[number,number];particleR?:number;timeVariance?:number;colors?:number[];initialActiveIndex?:number;}
const props=withDefaults(defineProps<GooeyNavProps>(),{animationTime:600,particleCount:15,particleDistances:()=>[90,10],particleR:100,timeVariance:300,colors:()=>[1,2,3,1,2,3,1,4],initialActiveIndex:0});
const containerRef=ref<HTMLDivElement|null>(null),navRef=ref<HTMLUListElement|null>(null),filterRef=ref<HTMLSpanElement|null>(null),textRef=ref<HTMLSpanElement|null>(null),activeIndex=ref(props.initialActiveIndex),reduced=ref(false);
let resizeObserver:ResizeObserver|null=null,motionQuery:MediaQueryList|null=null,alive=false;const timers=new Set<number>(),rafs=new Set<number>();
const schedule=(callback:()=>void,delay:number)=>{const id=window.setTimeout(()=>{timers.delete(id);if(alive)callback();},delay);timers.add(id);return id;};
const nextFrame=(callback:()=>void)=>{const id=requestAnimationFrame(()=>{rafs.delete(id);if(alive)callback();});rafs.add(id);};
const clearParticles=()=>{timers.forEach(id=>clearTimeout(id));timers.clear();rafs.forEach(id=>cancelAnimationFrame(id));rafs.clear();filterRef.value?.querySelectorAll('.particle').forEach(p=>p.remove());};
const noise=(n=1)=>n/2-Math.random()*n;
const getXY=(distance:number,pointIndex:number,totalPoints:number):[number,number]=>{const angle=(360+noise(8))/Math.max(1,totalPoints)*pointIndex*Math.PI/180;return[distance*Math.cos(angle),distance*Math.sin(angle)];};
const createParticle=(i:number,t:number,d:[number,number],r:number)=>{const rotate=noise(r/10),palette=props.colors.length?props.colors:[1];return{start:getXY(d[0],props.particleCount-i,props.particleCount),end:getXY(d[1]+noise(7),props.particleCount-i,props.particleCount),time:t,scale:1+noise(.2),color:palette[Math.floor(Math.random()*palette.length)],rotate:rotate>0?(rotate+r/20)*10:(rotate-r/20)*10};};
const makeParticles=(element:HTMLElement)=>{if(reduced.value||!alive)return;const d:[number,number]=props.particleDistances,r=props.particleR,bubbleTime=props.animationTime*2+props.timeVariance;element.style.setProperty('--time',`${bubbleTime}ms`);element.classList.remove('active');for(let i=0;i<props.particleCount;i++){const t=Math.max(60,props.animationTime*2+noise(props.timeVariance*2)),p=createParticle(i,t,d,r);schedule(()=>{const particle=document.createElement('span'),point=document.createElement('span');particle.classList.add('particle');particle.style.setProperty('--start-x',`${p.start[0]}px`);particle.style.setProperty('--start-y',`${p.start[1]}px`);particle.style.setProperty('--end-x',`${p.end[0]}px`);particle.style.setProperty('--end-y',`${p.end[1]}px`);particle.style.setProperty('--time',`${p.time}ms`);particle.style.setProperty('--scale',`${p.scale}`);particle.style.setProperty('--color',`var(--color-${p.color}, white)`);particle.style.setProperty('--rotate',`${p.rotate}deg`);point.classList.add('point');particle.append(point);element.append(particle);nextFrame(()=>element.classList.add('active'));schedule(()=>particle.remove(),t);},30);}if(props.particleCount<=0)element.classList.add('active');};
const updateEffectPosition=(element:HTMLElement)=>{if(!containerRef.value||!filterRef.value||!textRef.value)return;const containerRect=containerRef.value.getBoundingClientRect(),pos=element.getBoundingClientRect(),styles={left:`${pos.x-containerRect.x}px`,top:`${pos.y-containerRect.y}px`,width:`${pos.width}px`,height:`${pos.height}px`};Object.assign(filterRef.value.style,styles);Object.assign(textRef.value.style,styles);textRef.value.textContent=element.textContent?.trim()??'';};
const syncPosition=()=>{if(!alive)return;const element=navRef.value?.querySelectorAll('li')[activeIndex.value] as HTMLElement|undefined;if(element){updateEffectPosition(element);textRef.value?.classList.add('active');filterRef.value?.classList.add('active');}};
const handleClick=(event:MouseEvent,index:number)=>{const link=event.currentTarget as HTMLAnchorElement,li=link.parentElement;if(!li)return;if(activeIndex.value===index)return;clearParticles();activeIndex.value=index;updateEffectPosition(li);if(textRef.value){textRef.value.classList.remove('active');void textRef.value.offsetWidth;textRef.value.classList.add('active');}if(filterRef.value&&!reduced.value)makeParticles(filterRef.value);};
const handleKeyDown=(event:KeyboardEvent)=>{if(event.key===' '){event.preventDefault();(event.currentTarget as HTMLAnchorElement).click();}};
const onMotion=()=>{reduced.value=motionQuery?.matches??false;clearParticles();syncPosition();};
watch(()=>props.items,async()=>{activeIndex.value=Math.min(Math.max(0,activeIndex.value),Math.max(0,props.items.length-1));await nextTick();syncPosition();},{deep:true});
onMounted(async()=>{alive=true;motionQuery=matchMedia('(prefers-reduced-motion: reduce)');reduced.value=motionQuery.matches;motionQuery.addEventListener('change',onMotion);activeIndex.value=Math.min(Math.max(0,props.initialActiveIndex),Math.max(0,props.items.length-1));await nextTick();if(!alive)return;syncPosition();if('ResizeObserver'in window){resizeObserver=new ResizeObserver(syncPosition);if(containerRef.value)resizeObserver.observe(containerRef.value);if(navRef.value)resizeObserver.observe(navRef.value);}window.addEventListener('resize',syncPosition);document.fonts?.ready.then(()=>{if(alive)syncPosition();}).catch(()=>{});});
onUnmounted(()=>{alive=false;resizeObserver?.disconnect();motionQuery?.removeEventListener('change',onMotion);window.removeEventListener('resize',syncPosition);clearParticles();});
</script>
<template>
<div class="xxy-gooey" :class="{'gn-reduced':reduced}"><div class="gn-container" ref="containerRef"><nav class="gn-nav" aria-label="Explore profile"><ul ref="navRef" class="gn-list"><li v-for="(item,index) in items" :key="item.href || item.label" :class="{active:activeIndex===index}"><a :href="item.href || undefined" @click="event=>handleClick(event,index)" @keydown="handleKeyDown">{{item.label}}</a></li></ul></nav><span class="effect filter" ref="filterRef" aria-hidden="true"/><span class="effect text" ref="textRef" aria-hidden="true"/></div></div>
</template>
<style>
.xxy-gooey{--color-1:#ffffff;--color-2:#f2a71b;--color-3:#f8c85c;--color-4:#ffe6ad;position:relative;width:max-content;max-width:100%;isolation:isolate;font:inherit}.xxy-gooey .gn-container{position:relative}.xxy-gooey .gn-nav{display:flex;position:relative;inset:auto;width:100%;z-index:auto;background:transparent;color:inherit;justify-content:flex-start;align-items:stretch;padding:0;backdrop-filter:none;transform:translate3d(0,0,.01px)}.xxy-gooey .gn-list{display:flex;flex-wrap:wrap;gap:14px;list-style:none;padding:0;margin:0;position:relative;z-index:3;color:white;text-shadow:0 1px 1px hsl(205deg 30% 10% / .2)}.xxy-gooey .gn-list li{border-radius:999px;position:relative;cursor:pointer;transition:background-color .3s,color .3s,box-shadow .3s;box-shadow:0 0 .5px 1.5px transparent;color:white;max-width:100%;padding:0;margin:0}.xxy-gooey .gn-list a{display:inline-block;position:relative;padding:.7em 1.1em;font-size:15px;line-height:1.5;text-decoration:none;color:inherit;text-align:center;overflow-wrap:normal;border-radius:999px}.xxy-gooey .gn-list a:focus-visible{outline:3px solid #f2a71b;outline-offset:5px}.xxy-gooey .gn-list li.active{color:#0b1f33;text-shadow:none}.xxy-gooey .gn-list li::after{content:'';position:absolute;inset:0;border-radius:999px;background:white;opacity:0;transform:scale(0);transition:opacity .3s ease,transform .3s ease;z-index:-1}.xxy-gooey .gn-list li.active::after{opacity:1;transform:scale(1)}.xxy-gooey .effect{position:absolute;opacity:1;pointer-events:none;display:grid;place-items:center;z-index:1;border-radius:999px}.xxy-gooey .effect.text{color:white;transition:color .3s ease;font-size:15px;line-height:1.5;text-align:center;padding:.7em 1.1em;z-index:4}.xxy-gooey .effect.text.active{color:#0b1f33}.xxy-gooey .effect.filter{filter:blur(7px) contrast(100) blur(0);mix-blend-mode:lighten}.xxy-gooey .effect.filter::before{content:'';position:absolute;inset:-75px;z-index:-2;background:black}.xxy-gooey .effect.filter::after{content:'';position:absolute;inset:0;background:white;transform:scale(0);opacity:0;z-index:-1;border-radius:9999px}.xxy-gooey .effect.active::after{animation:xxy-gn-pill .3s ease both}.xxy-gooey .particle,.xxy-gooey .point{display:block;opacity:0;width:20px;height:20px;border-radius:9999px;transform-origin:center}.xxy-gooey .particle{--time:5s;position:absolute;top:calc(50% - 8px);left:calc(50% - 8px);animation:xxy-gn-particle var(--time) ease 1 -350ms}.xxy-gooey .point{background:var(--color);opacity:1;animation:xxy-gn-point var(--time) ease 1 -350ms}
@keyframes xxy-gn-pill{to{transform:scale(1);opacity:1}}
@keyframes xxy-gn-particle{0%{transform:rotate(0deg) translate(var(--start-x),var(--start-y));opacity:1;animation-timing-function:cubic-bezier(.55,0,1,.45)}70%{transform:rotate(calc(var(--rotate) * .5)) translate(calc(var(--end-x) * 1.2),calc(var(--end-y) * 1.2));opacity:1;animation-timing-function:ease}85%{transform:rotate(calc(var(--rotate) * .66)) translate(var(--end-x),var(--end-y));opacity:1}100%{transform:rotate(calc(var(--rotate) * 1.2)) translate(calc(var(--end-x) * .5),calc(var(--end-y) * .5));opacity:1}}
@keyframes xxy-gn-point{0%{transform:scale(0);opacity:0;animation-timing-function:cubic-bezier(.55,0,1,.45)}25%{transform:scale(calc(var(--scale) * .25))}38%{opacity:1}65%{transform:scale(var(--scale));opacity:1;animation-timing-function:ease}85%{transform:scale(var(--scale));opacity:1}100%{transform:scale(0);opacity:0}}
.xxy-gooey.gn-reduced .effect{display:none}.xxy-gooey.gn-reduced .gn-list li,.xxy-gooey.gn-reduced .gn-list li::after{transition:none}@media(max-width:760px){.xxy-gooey .gn-list{gap:10px}.xxy-gooey .gn-list a,.xxy-gooey .effect.text{font-size:14px}}@media(prefers-reduced-motion:reduce){.xxy-gooey .effect{display:none}.xxy-gooey .particle,.xxy-gooey .point{animation:none}.xxy-gooey .gn-list li,.xxy-gooey .gn-list li::after{transition:none}}@media print{.xxy-gooey .effect{display:none}.xxy-gooey .gn-list li{color:black!important}.xxy-gooey .gn-list li::after{background:transparent}}
</style>
